using System.Buffers.Binary;
using System.Collections.Concurrent;
using System.Diagnostics;
using System.Net.Sockets;
using System.Text;
using Allegiance.Core.Transport;

var site = new Site();
var host = new TcpTransport(site, TransportMode.Pool, 1) { Egress = new EgressAccounting() };
var clients = new List<TcpClient>();
TcpTransport.NoWriteProgressTimeout = TimeSpan.FromSeconds(2);
(ConnectionId, TcpClient) Connect(string name, bool paused)
{
    var c = new TcpClient { NoDelay = true };
    clients.Add(c);
    if (paused) c.ReceiveBufferSize = 1024;
    c.Connect("127.0.0.1", host.BoundPort);
    byte[] body = Encoding.UTF8.GetBytes(name), greet = new byte[5+body.Length];
    greet[0] = 1;
    BinaryPrimitives.WriteUInt32LittleEndian(greet.AsSpan(1), (uint)body.Length);
    body.CopyTo(greet, 5); c.GetStream().Write(greet);
    if (!SpinWait.SpinUntil(() => site.Joined.ContainsKey(name), 10000)) throw new Exception("join");
    return (site.Joined[name],c);
}
try
{
    host.Host(0);
    var slow = Enumerable.Range(0,3).Select(i=>Connect("slow-"+i,true)).ToArray();
    var healthy = Enumerable.Range(0,16).Select(i=>Connect("healthy-"+i,false)).ToArray();
    byte[] flood = new byte[2*1024*1024];
    foreach (var p in slow) host.Send(p.Item1,flood,true);
    Thread.Sleep(200);
    byte[] body = new byte[64], received = new byte[69];
    double maxLatency = 0;
    int rounds=0;
    var timer=Stopwatch.StartNew();
    do
    {
        BinaryPrimitives.WriteInt32LittleEndian(body, rounds);
        long start=Stopwatch.GetTimestamp();
        foreach(var p in healthy)host.Send(p.Item1,body,true);
        foreach(var p in healthy)
        {
            p.Item2.ReceiveTimeout=1500;p.Item2.GetStream().ReadExactly(received);
            if(received[0]!=2 || !body.AsSpan().SequenceEqual(received.AsSpan(5)))throw new Exception("framing");
        }
        double ms=Stopwatch.GetElapsedTime(start).TotalMilliseconds;
        if(ms>=1500)throw new Exception("latency "+ms);
        maxLatency=Math.Max(maxLatency,ms);
        foreach(var p in slow)host.SendCoalescing(p.Item1,body,1);
        rounds++; Thread.Sleep(25);
    }while((rounds<40 || slow.Any(p=>!site.Left.ContainsKey(p.Item1))) && timer.Elapsed.TotalSeconds<10);
    var reasons=host.DrainDisconnectCounts();
    if(slow.Any(p=>!site.Left.ContainsKey(p.Item1)) || healthy.Any(p=>site.Left.ContainsKey(p.Item1)) || reasons.GetValueOrDefault(DisconnectReason.NoWriteProgress)!=3 || reasons.Values.Sum()!=3)throw new Exception("disconnects");
    Console.WriteLine($"BASELINE 6c3e54ad: slow=3 healthy=16 workers=1 rounds={rounds} maxHealthyDeliveryMs={maxLatency:0.000} NoWriteProgress=3 PASS");
}
finally {host.Shutdown();foreach(var c in clients)c.Dispose();}
class Site:ITransportSite
{
    public ConcurrentDictionary<string,ConnectionId> Joined=new();
    public ConcurrentDictionary<ConnectionId,byte> Left=new();
    public void OnPeerJoined(ConnectionId id,string name)=>Joined[name]=id;
    public void OnPeerLeft(ConnectionId id)=>Left[id]=0;
    public void OnSessionLost(){}
    public void OnReceive(ConnectionId from,ReadOnlySpan<byte> data){}
}
